import { describe, expect, it } from "vitest";
import { withoutFooter } from "./tidy-footers.mjs";

const LINK = "https://claude.ai/code/session_0123456789";

describe("the footer", () => {
  it("comes off a description, with the line above it", () => {
    const body = `The problem.\n\n## Tested\n\n- All pass.\n\n---\n\n_Generated by [Claude Code](${LINK})_\n`;
    expect(withoutFooter(body)).toBe("The problem.\n\n## Tested\n\n- All pass.\n");
  });

  it("comes off a comment without a line, and in its other wordings", () => {
    expect(withoutFooter(`Thanks for reporting this!\n\n_Generated by [Claude Code](${LINK})_`)).toBe("Thanks for reporting this!\n");
    expect(withoutFooter(`Fixed.\n\n🤖 Generated with [Claude Code](${LINK})\n\n`)).toBe("Fixed.\n");
  });

  it("leaves the rest alone, horizontal rules too", () => {
    expect(withoutFooter("Before.\n\n---\n\nAfter, made with [Claude Code](https://claude.com).\n")).toBeNull();
    expect(withoutFooter("_Generated by [Claude Code](x)_ is what it said, before the end.\n")).toBeNull();
    expect(withoutFooter(`Quoted:\n\n_Generated by [Claude Code](${LINK})_\n\nand then more.\n`)).toBeNull();
    expect(withoutFooter("")).toBeNull();
  });
});
